typedef float rational_t;
class vector2d {
public:
    rational_t x, y;
    vector2d() {}
    vector2d(rational_t a, rational_t b) : x(a), y(b) {}
};
class texture_coord : public vector2d {
public:
    texture_coord() {}
    texture_coord(float u, float v) : vector2d(u, v) {}
};
class rectf {
public:
    vector2d tl, br;
    rational_t get_left() const { return tl.x; }
    rational_t get_top() const { return tl.y; }
    rational_t get_right() const { return br.x; }
    rational_t get_bottom() const { return br.y; }
};
class mat_fac {
public:
    virtual ~mat_fac();
private:
    char material[0x108];
} __attribute__((aligned(8)));
class widget {
    char padding0[0x14];
protected:
    unsigned int flags;
    char padding1[0x108];
    vector2d abs_S;
    rectf subrect;
    void *vtable;
};
class bitmap_widget : public widget {
public:
    bool is_open() { return flags & 0x00000002; }
    void set_tc();
protected:
    rational_t w, h, hw, hh;
    int nframes;
    mat_fac mat;
    int index;
    bool playing;
    rational_t frame_delay, frame_time, last_time;
    texture_coord tc[4];
};

void bitmap_widget::set_tc()
{
  if ( !is_open() ) return;

  tc[0] = texture_coord((subrect.get_left () + 0.5f) / ( w * abs_S.x ), (subrect.get_top   () + 0.5f) / ( h * abs_S.y) );
  tc[1] = texture_coord((subrect.get_right() - 0.5f) / ( w * abs_S.x ), (subrect.get_top   () + 0.5f) / ( h * abs_S.y) );
  tc[2] = texture_coord((subrect.get_left () + 0.5f) / ( w * abs_S.x ), (subrect.get_bottom() - 0.5f) / ( h * abs_S.y) );
  tc[3] = texture_coord((subrect.get_right() - 0.5f) / ( w * abs_S.x ), (subrect.get_bottom() - 0.5f) / ( h * abs_S.y) );
}
